fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0usize;
    let mut right = v.len() - 1;

    // Invariant:
    //  - 0 <= left <= right < v.len()
    //  - k appears at least once somewhere in v[left..=right]
    // Each iteration reduces the interval size strictly, ensuring termination.

    while left < right {
        let mid = left + (right - left) / 2;
        // if v[mid] < k, target must be in the right half (excluding mid)
        // else target is in left half (including mid)
        if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid; 
        }
    }

    // After loop ends, left == right and v[left] == k (due to guarantees)
    left
}